   548→
   549→@layer utils {
   550→  .text-gradient {
   551→    @apply bg-clip-text text-transparent;
   552→  }
   553→
   554→  /* Moodday Glass Card */
   555→  .glass-card {
   556→    background: rgba(255, 255, 255, 0.8);
   557→    backdrop-filter: blur(12px);
   558→    -webkit-backdrop-filter: blur(12px);
   559→    border: 1px solid rgba(255, 255, 255, 0.6);
   560→  }
   561→
   562→  .dark .glass-card {
   563→    background: rgba(36, 40, 48, 0.8);
   564→    border: 1px solid rgba(255, 255, 255, 0.1);
   565→  }
   566→
   567→  /* Moodday Shadow Soft */
   568→  .shadow-soft {
   569→    box-shadow: 0 10px 25px -5px rgba(43, 160, 159, 0.1), 0 8px 10px -6px rgba(43, 160, 159, 0.05);
   570→  }
   571→
   572→  /* Moodday Shadow Glass */
   573→  .shadow-glass {
   574→    box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.07);
   575→  }
   576→
   577→  .dark .shadow-soft {
   578→    box-shadow: 0 10px 25px -5px rgba(61, 165, 184, 0.15), 0 8px 10px -6px rgba(61, 165, 184, 0.1);
   579→  }
   580→
   581→  /* Moodday Background Colors */
   582→  .bg-warm-bg {
   583→    background-color: var(--warm-bg);
   584→  }
   585→
   586→  .bg-warm-panel {
   587→    background-color: var(--warm-panel);
   588→  }
   589→
   590→  .bg-primary-soft {
   591→    background-color: rgba(43, 160, 159, 0.1);
   592→  }
   593→
   594→  .bg-sage-soft {
   595→    background-color: rgba(72, 168, 120, 0.1);
   596→  }
   597→
   598→  .bg-lavender-soft {
   599→    background-color: rgba(212, 197, 232, 0.2);
   600→  }
   601→
   602→  /* Moodday Text Colors */
   603→  .text-primary-darkest {
   604→    color: var(--primary-darkest);
   605→  }
   606→
   607→  .text-sage {
   608→    color: var(--sage);
   609→  }
   610→
   611→  .text-sage-dark {
   612→    color: var(--sage-dark);
   613→  }
   614→
   615→  .text-lavender {
   616→    color: var(--lavender);
   617→  }
   618→
   619→  .text-lavender-dark {
   620→    color: var(--lavender-dark);
   621→  }
   622→
   623→  /* Moodday Border Radius */
   624→  .rounded-3xl {
   625→    border-radius: 32px;
   626→  }
   627→
   628→  /* Moodday Active Nav Item */
   629→  .nav-item-active {
   630→    @apply bg-primary text-white font-bold;
   631→  }
   632→
   633→  /* Moodday Blob Decoration */
   634→  .blob {
   635→    position: fixed;
   636→    width: 600px;
   637→    height: 600px;
   638→    filter: blur(100px);
   639→    border-radius: 50%;
   640→    z-index: -1;
   641→    opacity: 0.4;
   642→    pointer-events: none;
   643→  }
   644→
   645→  .blob-primary {
   646→    background: rgba(43, 160, 159, 0.2);
   647→  }
   648→
   649→  .blob-lavender {
   650→    background: rgba(212, 197, 232, 0.3);
   651→  }
   652→
   653→  /* Hide scrollbar utility */
   654→  .no-scrollbar::-webkit-scrollbar {
   655→    display: none;
   656→  }
   657→
   658→  .no-scrollbar {
   659→    -ms-overflow-style: none;
   660→    scrollbar-width: none;
   661→  }
   662→
   663→  /* Pulse soft animation */
   664→  @keyframes pulse-soft {
   665→    0%, 100% { opacity: 1; }
   666→    50% { opacity: 0.7; }
   667→  }
   668→
   669→  .animate-pulse-soft {
   670→    animation: pulse-soft 3s infinite;
   671→  }
   672→
   673→  .bg-grid {
   674→    --bg-grid-color: hsl(0 0% 100% / 0.1);
   675→    background-color: transparent;
   676→    background-image:
   677→      linear-gradient(90deg, var(--bg-grid-color) 1px, transparent 1px),
   678→      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
   679→    background-size: 64px 64px;
   680→  }
   681→}
   682→
   683→/* Other styles */
   684→
   685→.citation {
   686→  position: relative;
   687→  display: inline-block;
   688→  padding: 4px;
   689→  border-radius: 0.5rem;
   690→  color: var(--foreground);
   691→  font-style: italic;
   692→  --gap: -16px;
   693→}
   694→
   695→.citation::before {
   696→  content: "“";
   697→  font-size: 3rem;
   698→  position: absolute;
   699→  top: -12px;
   700→  left: -12px;
   701→  line-height: 1;
   702→  color: hsl(var(--primary));
   703→}
   704→
   705→.citation::after {
   706→  content: "”";
