   708→  position: absolute;
   709→  bottom: -16px;
   710→  right: -4px;
   711→  line-height: 1;
   712→  color: hsl(var(--primary));
   713→}
   714→
   715→.citation strong {
   716→  font-weight: 700;
   717→  background: hsl(var(--primary) / 0.5);
   718→  display: inline;
   719→  padding: 2px;
   720→  margin: -2px;
   721→}
   722→
   723→.dot-pattern {
   724→  background-color: var(--dot-background);
   725→  opacity: 0.8;
   726→  background-image: radial-gradient(
   727→    var(--dot-color) 0.5px,
   728→    var(--dot-background) 0.5px
   729→  );
   730→  background-size: var(--size, 10px) var(--size, 10px);
   731→}
   732→
   733→html.dark .shiki,
   734→html.dark .shiki span {
   735→  color: var(--shiki-dark) !important;
   736→  background-color: var(--shiki-dark-bg) !important;
   737→  /* Optional, if you also want font styles */
   738→  font-style: var(--shiki-dark-font-style) !important;
   739→  font-weight: var(--shiki-dark-font-weight) !important;
   740→  text-decoration: var(--shiki-dark-text-decoration) !important;
   741→}
   742→
   743→.prose {
   744→  code:not(pre code) {
   745→    &::after {
   746→      display: none;
   747→    }
   748→    &::before {
   749→      display: none;
   750→    }
   751→
   752→    background-color: var(--muted);
   753→    padding: calc(var(--spacing) * 1.5);
   754→    border-radius: var(--radius);
   755→  }
   756→}
   757→.chat-prose {
   758→  h1,
   759→  h2,
   760→  h3 {
