@import "tailwindcss";
@plugin "tailwindcss-animate";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-success-foreground: var(--success-foreground);
  --color-success: var(--success);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning: var(--warning);
  --color-info-foreground: var(--info-foreground);
  --color-info: var(--info);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: 24px;
  --radius-3xl: 32px;
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;

  /* Moodday Design System - Primary (Teal/Ocean) */
  --color-moodday-primary: #2BA09F;
  --color-moodday-primary-dark: #2A8FA8;
  --color-moodday-primary-light: #3DA5B8;
  --color-moodday-primary-darkest: #1D7680;

  /* Moodday Design System - Sage (Nature/Growth) */
  --color-moodday-sage: #48A878;
  --color-moodday-sage-dark: #3A956E;
  --color-moodday-sage-light: #6FBD94;

  /* Moodday Design System - Accents */
  --color-moodday-lavender: #D4C5E8;
  --color-moodday-lavender-dark: #B8A5D6;

  /* Moodday Design System - Warm Backgrounds */
  --color-moodday-warm-bg: #F8F7F3;
  --color-moodday-warm-panel: #F4F1ED;

  /* Moodday Design System - Emergency */
  --color-moodday-danger: #EF4444;

  /* Moodday Shadows */
  --shadow-soft: 0 10px 25px -5px rgba(43, 160, 159, 0.1), 0 8px 10px -6px rgba(43, 160, 159, 0.05);
  --shadow-glass: 0 8px 32px 0 rgba(31, 38, 135, 0.07);

  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }
    to {
      height: 0;
    }
  }
}

:root {
  /* Moodday uses warm off-white as the main background */
  --background: #F8F7F3;
  --foreground: #1F2937;
  --card: #FFFFFF;
  --card-foreground: #1F2937;
  --popover: #FFFFFF;
  --popover-foreground: #1F2937;

  /* Primary: Moodday Teal */
  --primary: #2BA09F;
  --primary-foreground: #FFFFFF;
  --primary-dark: #2A8FA8;
  --primary-light: #3DA5B8;
  --primary-darkest: #1D7680;

  /* Secondary: Moodday Sage */
  --secondary: #F4F1ED;
  --secondary-foreground: #1F2937;

  /* Muted */
  --muted: #F4F1ED;
  --muted-foreground: #6B7280;

  /* Accent: Lavender */
  --accent: #D4C5E8;
  --accent-foreground: #1F2937;

  /* Sage colors */
  --sage: #48A878;
  --sage-dark: #3A956E;
  --sage-light: #6FBD94;
  --sage-foreground: #FFFFFF;

  /* Lavender colors */
  --lavender: #D4C5E8;
  --lavender-dark: #B8A5D6;

  /* Warm backgrounds */
  --warm-bg: #F8F7F3;
  --warm-panel: #F4F1ED;

  /* Destructive/Emergency */
  --destructive: #EF4444;
  --destructive-foreground: #FFFFFF;

  /* Borders and inputs */
  --border: rgba(0, 0, 0, 0.06);
  --input: rgba(0, 0, 0, 0.06);
  --ring: #2BA09F;

  /* Charts - Moodday palette */
  --chart-1: #2BA09F;
  --chart-2: #48A878;
  --chart-3: #D4C5E8;
  --chart-4: #2A8FA8;
  --chart-5: #6FBD94;

  /* Border radius */
  --radius: 12px;

  /* Sidebar */
  --sidebar: #FFFFFF;
  --sidebar-foreground: #1F2937;
  --sidebar-primary: #2BA09F;
  --sidebar-primary-foreground: #FFFFFF;
  --sidebar-accent: rgba(43, 160, 159, 0.1);
  --sidebar-accent-foreground: #2BA09F;
  --sidebar-border: rgba(0, 0, 0, 0.06);
  --sidebar-ring: #2BA09F;

  /* Status colors */
  --success: #48A878;
  --success-foreground: #FFFFFF;

  --warning: hsl(24deg 94% 50%);
  --warning-foreground: hsl(24deg 97% 93%);

  --info: #2BA09F;
  --info-foreground: #FFFFFF;

  /* Patient Sidebar */
  --sidebar-patient: #F8F7F3;
  --sidebar-patient-accent: rgba(43, 160, 159, 0.1);
  --sidebar-patient-primary: #2BA09F;
}

.dark {
  /* Dark mode with Moodday palette */
  --background: #1A1D21;
  --foreground: #F8F7F3;
  --card: #242830;
  --card-foreground: #F8F7F3;
  --popover: #242830;
  --popover-foreground: #F8F7F3;

  /* Primary stays teal but slightly brighter for dark mode */
  --primary: #3DA5B8;
  --primary-foreground: #FFFFFF;
  --primary-dark: #2BA09F;
  --primary-light: #4DB8C9;
  --primary-darkest: #2A8FA8;

  /* Secondary */
  --secondary: #2D323A;
  --secondary-foreground: #F8F7F3;

  /* Muted */
  --muted: #2D323A;
  --muted-foreground: #9CA3AF;

  /* Accent: Lavender lighter */
  --accent: #3D3352;
  --accent-foreground: #D4C5E8;

  /* Sage colors */
  --sage: #6FBD94;
  --sage-dark: #48A878;
  --sage-light: #8FD4AB;
  --sage-foreground: #1A1D21;

  /* Lavender colors */
  --lavender: #B8A5D6;
  --lavender-dark: #9785C2;

  /* Warm backgrounds (darker versions) */
  --warm-bg: #1A1D21;
  --warm-panel: #242830;

  /* Destructive/Emergency */
  --destructive: #F87171;
  --destructive-foreground: #1A1D21;

  /* Borders and inputs */
  --border: rgba(255, 255, 255, 0.1);
  --input: rgba(255, 255, 255, 0.1);
  --ring: #3DA5B8;

  /* Charts - Moodday palette for dark */
  --chart-1: #3DA5B8;
  --chart-2: #6FBD94;
  --chart-3: #B8A5D6;
  --chart-4: #4DB8C9;
  --chart-5: #8FD4AB;

  /* Sidebar */
  --sidebar: #1F232A;
  --sidebar-foreground: #F8F7F3;
  --sidebar-primary: #3DA5B8;
  --sidebar-primary-foreground: #FFFFFF;
  --sidebar-accent: rgba(61, 165, 184, 0.15);
  --sidebar-accent-foreground: #3DA5B8;
  --sidebar-border: rgba(255, 255, 255, 0.1);
  --sidebar-ring: #3DA5B8;

  /* Status colors */
  --success: #6FBD94;
  --success-foreground: #1A1D21;

  --warning: hsl(24deg 94% 60%);
  --warning-foreground: #1A1D21;

  --info: #3DA5B8;
  --info-foreground: #1A1D21;

  /* Patient Sidebar */
  --sidebar-patient: #1F232A;
  --sidebar-patient-accent: rgba(61, 165, 184, 0.15);
  --sidebar-patient-primary: #3DA5B8;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  .typography {
    max-width: 65ch;
    color: var(--color-foreground);
  }
  .typography h1:not(.not-typography h1) {
    scroll-margin: calc(var(--spacing) * 20);
    font-size: var(--text-4xl);
    line-height: var(--text-4xl--line-height);
    font-weight: 800;
    letter-spacing: var(--tracking-tight);
  }
  .typography h2:not(.not-typography h2) {
    scroll-margin: calc(var(--spacing) * 20);
    border-bottom: 1px solid var(--color-border);
    padding-bottom: calc(var(--spacing) * 2);
    font-size: var(--text-3xl);
    line-height: var(--text-3xl--line-height);
    font-weight: 600;
    letter-spacing: var(--tracking-tight);
    margin-top: calc(var(--spacing) * 12);
  }
  .typography h2:not(.not-typography h2):first-child {
    margin-top: 0;
  }
  .typography h3:not(.not-typography h3) {
    scroll-margin: calc(var(--spacing) * 20);
    font-size: var(--text-2xl);
    line-height: var(--text-2xl--line-height);
    font-weight: 600;
    letter-spacing: var(--tracking-tight);
    margin-top: calc(var(--spacing) * 12);
  }
  .typography h3:not(.not-typography h3):first-child {
    margin-top: 0;
  }
  .typography h4:not(.not-typography h4) {
    scroll-margin: calc(var(--spacing) * 20);
    font-size: var(--text-xl);
    line-height: var(--text-xl--line-height);
    font-weight: 600;
    letter-spacing: var(--tracking-tight);
    margin-top: calc(var(--spacing) * 12);
  }
  .typography h4:not(.not-typography h4):first-child {
    margin-top: 0;
  }
  .typography h5:not(.not-typography h5) {
    scroll-margin: calc(var(--spacing) * 20);
    font-size: var(--text-lg);
    line-height: var(--text-lg--line-height);
    font-weight: 600;
    letter-spacing: var(--tracking-tight);
    margin-top: calc(var(--spacing) * 12);
  }
  .typography h5:not(.not-typography h5):first-child {
    margin-top: 0;
  }
  .typography h6:not(.not-typography h6) {
    scroll-margin: calc(var(--spacing) * 20);
    font-size: var(--text-base);
    line-height: var(--text-base--line-height);
    font-weight: 600;
    letter-spacing: var(--tracking-tight);
    margin-top: calc(var(--spacing) * 12);
  }
  .typography h6:not(.not-typography h6):first-child {
    margin-top: 0;
  }
  .typography h1:not(.not-typography h1) + p,
  .typography h2:not(.not-typography h2) + p,
  .typography h3:not(.not-typography h3) + p,
  .typography h4:not(.not-typography h4) + p,
  .typography h5:not(.not-typography h5) + p,
  .typography h6:not(.not-typography h6) + p {
    margin-top: 0;
  }
  .typography p:not(.not-typography p) {
    line-height: 1.75;
  }
  .typography p:not(.not-typography p):not(:first-child) {
    margin-top: calc(var(--spacing) * 6);
  }
  .typography li:not(.not-typography li) {
    line-height: 1.75;
  }
  .typography a:not(.not-typography a) {
    font-weight: 500;
    color: var(--color-primary);
    text-decoration: underline;
    text-underline-offset: var(--spacing);
  }
  .typography blockquote:not(.not-typography blockquote) {
    margin-top: calc(var(--spacing) * 6);
    border-left: 2px solid var(--color-border);
    padding-left: calc(var(--spacing) * 6);
    font-style: italic;
  }
  .typography table:not(.not-typography table) {
    margin-top: calc(var(--spacing) * 6);
    margin-bottom: calc(var(--spacing) * 6);
    width: 100%;
    overflow-y: auto;
  }
  .typography table:not(.not-typography table) thead tr {
    margin: 0;
    border-top: 1px solid var(--color-border);
    padding: 0;
  }
  .typography table:not(.not-typography table) thead tr:nth-child(even) {
    background-color: var(--color-muted);
  }
  .typography table:not(.not-typography table) th {
    border: 1px solid var(--color-border);
    padding: calc(var(--spacing) * 2) calc(var(--spacing) * 4);
    text-align: left;
    font-weight: 700;
  }
  .typography table:not(.not-typography table) th[align="center"] {
    text-align: center;
  }
  .typography table:not(.not-typography table) th[align="right"] {
    text-align: right;
  }
  .typography table:not(.not-typography table) tbody tr {
    margin: 0;
    border-top: 1px solid var(--color-border);
    padding: 0;
  }
  .typography table:not(.not-typography table) tbody tr:nth-child(even) {
    background-color: var(--color-muted);
  }
  .typography table:not(.not-typography table) td {
    border: 1px solid var(--color-border);
    padding: calc(var(--spacing) * 2) calc(var(--spacing) * 4);
    text-align: left;
  }
  .typography table:not(.not-typography table) td[align="center"] {
    text-align: center;
  }
  .typography table:not(.not-typography table) td[align="right"] {
    text-align: right;
  }
  .typography ul:not(.not-typography ul) {
    margin-top: calc(var(--spacing) * 6);
    margin-left: calc(var(--spacing) * 6);
    list-style: disc;
  }
  .typography ul:not(.not-typography ul) > li {
    margin-top: calc(var(--spacing) * 2);
  }
  .typography ul:not(.not-typography ul) p {
    margin-top: 0;
    margin-bottom: 0;
    display: inline;
  }
  .typography ol:not(.not-typography ol) {
    margin-top: calc(var(--spacing) * 6);
    margin-left: calc(var(--spacing) * 6);
    list-style: decimal;
  }
  .typography ol:not(.not-typography ol) > li {
    margin-top: calc(var(--spacing) * 2);
  }
  .typography ol:not(.not-typography ol) p {
    margin-top: 0;
    margin-bottom: 0;
    display: inline;
  }
  .typography pre:not(.not-typography pre) {
    background-color: var(--color-muted);
    border-radius: calc(var(--radius) - 2px);
    padding: calc(var(--spacing) * 4);
    margin-top: calc(var(--spacing) * 6);
    margin-bottom: calc(var(--spacing) * 6);
    font-size: var(--text-sm);
    line-height: var(--text-sm--line-height);
    overflow-y: auto;
  }
  .typography code:not(pre code):not(.not-typography code) {
    position: relative;
    border-radius: var(--radius);
    background-color: var(--color-muted);
    padding: calc(var(--spacing) * 0.2) calc(var(--spacing) * 0.3);
    font-family: var(--font-mono);
    font-size: var(--text-sm);
    line-height: var(--text-sm--line-height);
    font-weight: 600;
  }
  .typography .lead:not(.not-typography .lead) {
    font-size: var(--text-xl);
    line-height: var(--text-xl--line-height);
    color: var(--color-muted-foreground);
  }
  .typography .large:not(.not-typography .large) {
    font-size: var(--text-lg);
    line-height: var(--text-lg--line-height);
    font-weight: 600;
  }
  .typography .small:not(.not-typography .small) {
    font-size: var(--text-sm);
    line-height: 1;
    font-weight: 500;
  }
  .typography .muted:not(.not-typography .muted) {
    font-size: var(--text-sm);
    line-height: var(--text-sm--line-height);
    color: var(--color-muted-foreground);
  }
  .typography img:not(.not-typography img),
  .typography picture:not(.not-typography picture),
  .typography video:not(.not-typography video) {
    margin-top: calc(var(--spacing) * 6);
    margin-bottom: calc(var(--spacing) * 6);
  }
  .typography picture > img:not(.not-typography picture > img) {
    margin-top: 0;
    margin-bottom: 0;
  }
  .typography kbd:not(.not-typography kbd) {
    border-radius: calc(var(--radius) - 2px);
    background-color: var(--color-muted);
    padding: calc(var(--spacing) * 0.5) calc(var(--spacing) * 1.5);
    font-size: var(--text-xs);
    line-height: var(--text-xs--line-height);
    font-weight: 600;
  }
  .typography hr {
    margin-top: calc(var(--spacing) * 10);
    margin-bottom: calc(var(--spacing) * 10);
  }
  .typography dl:not(.not-typography dl) {
    margin-top: calc(var(--spacing) * 6);
    margin-bottom: calc(var(--spacing) * 6);
  }
  .typography dl:not(.not-typography dl) dt {
    font-weight: 600;
    margin-top: calc(var(--spacing) * 6);
    letter-spacing: var(--tracking-tight);
  }
  .typography dl:not(.not-typography dl) dt:first-child {
    margin-top: 0;
  }
  .typography details:not(.not-typography details) {
    margin-top: calc(var(--spacing) * 6);
  }
  .typography details:not(.not-typography details) summary {
    cursor: pointer;
    font-weight: 600;
    margin-top: calc(var(--spacing) * 6);
    letter-spacing: var(--tracking-tight);
  }
  .typography details:not(.not-typography details) p:first-of-type {
    margin-top: calc(var(--spacing) * 2);
  }
  .typography mark:not(.not-typography mark) {
    background-color: var(--color-yellow-300);
  }
  .typography small:not(.not-typography small) {
    font-size: var(--text-xs);
    line-height: 1;
  }

  @media (min-width: 1024px) {
    .typography h1:not(.not-typography h1) {
      font-size: var(--text-5xl);
      line-height: var(--text-5xl--line-height);
    }
  }
}

@layer utils {
  .text-gradient {
    @apply bg-clip-text text-transparent;
  }

  /* Moodday Glass Card */
  .glass-card {
    background: rgba(255, 255, 255, 0.8);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.6);
  }

  .dark .glass-card {
    background: rgba(36, 40, 48, 0.8);
    border: 1px solid rgba(255, 255, 255, 0.1);
  }

  /* Moodday Shadow Soft */
  .shadow-soft {
    box-shadow: 0 10px 25px -5px rgba(43, 160, 159, 0.1), 0 8px 10px -6px rgba(43, 160, 159, 0.05);
  }

  /* Moodday Shadow Glass */
  .shadow-glass {
    box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.07);
  }

  .dark .shadow-soft {
    box-shadow: 0 10px 25px -5px rgba(61, 165, 184, 0.15), 0 8px 10px -6px rgba(61, 165, 184, 0.1);
  }

  /* Moodday Background Colors */
  .bg-warm-bg {
    background-color: var(--warm-bg);
  }

  .bg-warm-panel {
    background-color: var(--warm-panel);
  }

  .bg-primary-soft {
    background-color: rgba(43, 160, 159, 0.1);
  }

  .bg-sage-soft {
    background-color: rgba(72, 168, 120, 0.1);
  }

  .bg-lavender-soft {
    background-color: rgba(212, 197, 232, 0.2);
  }

  /* Moodday Text Colors */
  .text-primary-darkest {
    color: var(--primary-darkest);
  }

  .text-sage {
    color: var(--sage);
  }

  .text-sage-dark {
    color: var(--sage-dark);
  }

  .text-lavender {
    color: var(--lavender);
  }

  .text-lavender-dark {
    color: var(--lavender-dark);
  }

  /* Moodday Border Radius */
  .rounded-3xl {
    border-radius: 32px;
  }

  /* Moodday Active Nav Item */
  .nav-item-active {
    @apply bg-primary text-white font-bold;
  }

  /* Moodday Blob Decoration */
  .blob {
    position: fixed;
    width: 600px;
    height: 600px;
    filter: blur(100px);
    border-radius: 50%;
    z-index: -1;
    opacity: 0.4;
    pointer-events: none;
  }

  .blob-primary {
    background: rgba(43, 160, 159, 0.2);
  }

  .blob-lavender {
    background: rgba(212, 197, 232, 0.3);
  }

  /* Hide scrollbar utility */
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }

  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  /* Pulse soft animation */
  @keyframes pulse-soft {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.7; }
  }

  .animate-pulse-soft {
    animation: pulse-soft 3s infinite;
  }

  .bg-grid {
    --bg-grid-color: hsl(0 0% 100% / 0.1);
    background-color: transparent;
    background-image:
      linear-gradient(90deg, var(--bg-grid-color) 1px, transparent 1px),
      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
    background-size: 64px 64px;
  }
}

/* Other styles */

.citation {
  position: relative;
  display: inline-block;
  padding: 4px;
  border-radius: 0.5rem;
  color: var(--foreground);
  font-style: italic;
  --gap: -16px;
}

.citation::before {
  content: "“";
  font-size: 3rem;
  position: absolute;
  top: -12px;
  left: -12px;
  line-height: 1;
  color: hsl(var(--primary));
}

.citation::after {
  content: "”";
  font-size: 3rem;
  position: absolute;
  bottom: -16px;
  right: -4px;
  line-height: 1;
  color: hsl(var(--primary));
}

.citation strong {
  font-weight: 700;
  background: hsl(var(--primary) / 0.5);
  display: inline;
  padding: 2px;
  margin: -2px;
}

.dot-pattern {
  background-color: var(--dot-background);
  opacity: 0.8;
  background-image: radial-gradient(
    var(--dot-color) 0.5px,
    var(--dot-background) 0.5px
  );
  background-size: var(--size, 10px) var(--size, 10px);
}

html.dark .shiki,
html.dark .shiki span {
  color: var(--shiki-dark) !important;
  background-color: var(--shiki-dark-bg) !important;
  /* Optional, if you also want font styles */
  font-style: var(--shiki-dark-font-style) !important;
  font-weight: var(--shiki-dark-font-weight) !important;
  text-decoration: var(--shiki-dark-text-decoration) !important;
}

.prose {
  code:not(pre code) {
    &::after {
      display: none;
    }
    &::before {
      display: none;
    }

    background-color: var(--muted);
    padding: calc(var(--spacing) * 1.5);
    border-radius: var(--radius);
  }
}
.chat-prose {
  h1,
  h2,
  h3 {
    font-size: 1rem !important;
  }
}

.code-example {
  & pre {
    margin: 0 !important;
  }
}

