                  <CalendarHeart className="size-6 text-primary" />
                </div>
              </div>

              {/* Stats Grid */}
              <div className="mb-6 grid grid-cols-3 gap-4">
                <StatCard
                  icon={<TrendingUp className="size-5 text-primary" />}
                  label="Humeur"
                  value="7.2"
                  suffix="/10"
                  trend="+0.4"
                  trendColor="text-sage"
                />
                <StatCard
                  icon={<CheckCircle className="size-5 text-sage" />}
                  label="Observance"
                  value="98"
                  suffix="%"
                  sublabel="28 jours"
                />
                <StatCard
                  icon={<Moon className="size-5 text-primary" />}
                  label="Sommeil"
                  value="7.5"
                  suffix="h"
                  sublabel="Qualité: 8/10"
                />
              </div>

              {/* Mood Slider Preview */}
              <div className="rounded-2xl bg-white/50 p-4 dark:bg-gray-800/50">
                <div className="mb-3 flex items-center justify-between">
                  <span className="text-sm font-semibold text-gray-600 uppercase tracking-wider dark:text-gray-400">
                    Humeur du jour
                  </span>
                  <span className="text-2xl">😊</span>
                </div>
                <div className="relative h-2 w-full rounded-full bg-gray-200 dark:bg-gray-700">
                  <motion.div
                    initial={{ width: 0 }}
                    animate={{ width: "72%" }}
                    transition={{ duration: 1, delay: 0.5 }}
                    className="absolute left-0 top-0 h-full rounded-full bg-gradient-to-r from-primary to-sage"
                  />
                  <motion.div
                    initial={{ left: 0 }}
                    animate={{ left: "72%" }}
                    transition={{ duration: 1, delay: 0.5 }}
                    className="absolute top-1/2 size-5 -translate-x-1/2 -translate-y-1/2 rounded-full border-4 border-white bg-primary shadow-lg dark:border-gray-800"
                  />
                </div>
                <div className="mt-2 flex justify-between text-xs text-gray-400">
                  <span>Très bas</span>
                  <span>Stable</span>
                  <span>Excellent</span>
                </div>
              </div>
            </div>

            {/* Floating Cards */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.6 }}
              className="glass-card absolute -bottom-4 -left-4 z-20 flex items-center gap-3 rounded-2xl p-4 shadow-soft"
            >
              <div className="flex size-10 items-center justify-center rounded-xl bg-sage/10">
                <CheckCircle className="size-5 text-sage" />
              </div>
              <div>
                <p className="text-sm font-bold text-gray-900 dark:text-gray-100">
                  Lamictal 200mg
                </p>
                <p className="text-xs text-sage">Pris à 08:00</p>
              </div>
            </motion.div>

            <motion.div
              initial={{ opacity: 0, y: -20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.8 }}
              className="glass-card absolute -right-4 top-4 z-20 rounded-2xl p-4 shadow-soft"
            >
              <p className="text-xs font-semibold text-gray-500 uppercase dark:text-gray-400">
                Prochaine séance
              </p>
              <p className="text-sm font-bold text-primary">
                Dr. Martin - Lundi 14h
              </p>
            </motion.div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}

function StatCard({
  icon,
  label,
  value,
  suffix,
  trend,
  trendColor,
  sublabel,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
  suffix: string;
  trend?: string;
  trendColor?: string;
  sublabel?: string;
}) {
  return (
    <div className="rounded-2xl bg-white/50 p-3 dark:bg-gray-800/50">
      <div className="mb-2 flex items-center gap-2">
        <div className="rounded-lg bg-primary/5 p-1.5 dark:bg-primary/10">
          {icon}
        </div>
        <span className="text-xs font-semibold text-gray-500 dark:text-gray-400">
          {label}
        </span>
      </div>
      <p className="text-xl font-bold text-gray-900 dark:text-gray-100">
        {value}
        <span className="text-xs font-normal text-gray-400">{suffix}</span>
      </p>
      {trend && (
        <p className={cn("mt-1 flex items-center gap-1 text-xs font-semibold", trendColor)}>
          <TrendingUp className="size-3" />
          {trend} vs semaine dernière
        </p>
      )}
      {sublabel && (
        <p className="mt-1 text-xs text-gray-400">{sublabel}</p>
      )}
    </div>
  );
}

input.content:
"use client";

import { cn } from "@/lib/utils";
import {
  BarChart3,
  Brain,
  FileText,
  Heart,
  Moon,
  Pill,
  Shield,
  Users,
} from "lucide-react";
import { motion } from "motion/react";

const features = [
  {
    icon: Brain,
    title: "Suivi d'humeur intelligent",
    description:
      "Enregistrez votre humeur en quelques secondes avec notre échelle intuitive. Visualisez vos tendances et identifiez les patterns.",
    color: "bg-primary/10 text-primary",
    gradient: "from-primary/20 to-primary/5",
  },
  {
    icon: Pill,
    title: "Gestion des traitements",
    description:
      "Suivez vos médicaments, dosages et prises quotidiennes. Recevez des rappels et voyez les corrélations avec votre humeur.",
    color: "bg-sage/10 text-sage",
    gradient: "from-sage/20 to-sage/5",
  },
  {
    icon: Moon,
    title: "Journal du sommeil",
    description:
      "Notez vos heures de sommeil et leur qualité. Comprenez l'impact du repos sur votre bien-être mental.",
    color: "bg-lavender/30 text-primary",
    gradient: "from-lavender/30 to-lavender/10",
  },
  {
    icon: BarChart3,
    title: "Analyses & tendances",
    description:
      "Visualisez vos données sur des graphiques clairs. Identifiez les facteurs qui influencent votre état mental.",
    color: "bg-primary/10 text-primary",
    gradient: "from-primary/20 to-primary/5",
  },
  {
    icon: FileText,
    title: "Export PDF médical",
    description:
      "Générez un rapport complet pour vos consultations. Facilitez la communication avec votre psychiatre ou thérapeute.",
    color: "bg-sage/10 text-sage",
    gradient: "from-sage/20 to-sage/5",
  },
  {
    icon: Users,
    title: "Cercle d'aidants",
    description:
      "Invitez un proche de confiance à suivre votre parcours. Partagez uniquement ce que vous souhaitez.",
    color: "bg-lavender/30 text-primary",
    gradient: "from-lavender/30 to-lavender/10",
  },
  {
    icon: Heart,
    title: "Zéro culpabilité",
    description:
      "Pas de streak, pas de gamification agressive. Votre bien-être passe avant tout, à votre rythme.",
    color: "bg-primary/10 text-primary",
    gradient: "from-primary/20 to-primary/5",
  },
  {
    icon: Shield,
    title: "Confidentialité totale",
    description:
      "Vos données sont chiffrées et vous appartiennent. Exportez ou supprimez tout à tout moment (RGPD).",
    color: "bg-sage/10 text-sage",
    gradient: "from-sage/20 to-sage/5",
  },
];

export function MooddayFeatures() {
  return (
    <section id="features" className="relative py-20 lg:py-32">
      {/* Background */}
      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-primary/5 to-transparent" />

      <div className="relative mx-auto max-w-7xl px-6 lg:px-8">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="mx-auto max-w-2xl text-center"
        >
          <span className="mb-4 inline-block rounded-full bg-primary/10 px-4 py-1.5 text-sm font-semibold text-primary">
            Fonctionnalités
          </span>
          <h2 className="mb-4 text-3xl font-bold tracking-tight text-gray-900 sm:text-4xl lg:text-5xl dark:text-gray-100">
            Tout ce dont vous avez besoin pour{" "}
            <span className="bg-gradient-to-r from-primary to-sage bg-clip-text text-transparent">
              prendre soin de vous
            </span>
          </h2>
          <p className="text-lg text-gray-600 dark:text-gray-400">
            Des outils pensés avec des professionnels de santé pour vous
            accompagner au quotidien dans votre parcours de santé mentale.
          </p>
        </motion.div>

        {/* Features Grid */}
        <div className="mt-16 grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
          {features.map((feature, index) => (
            <motion.div
              key={feature.title}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
            >
              <FeatureCard {...feature} />
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}

function FeatureCard({
  icon: Icon,
  title,
  description,
  color,
  gradient,
}: {
  icon: typeof Brain;
  title: string;
  description: string;
  color: string;
  gradient: string;
}) {
  return (
    <div className="glass-card group relative h-full overflow-hidden rounded-3xl p-6 shadow-soft transition-all hover:-translate-y-1 hover:shadow-lg">
      {/* Gradient Background on Hover */}
      <div
        className={cn(
          "absolute inset-0 bg-gradient-to-br opacity-0 transition-opacity group-hover:opacity-100",
          gradient
        )}
      />

      <div className="relative">
        {/* Icon */}
        <div
          className={cn(
            "mb-4 inline-flex size-12 items-center justify-center rounded-2xl",
            color
          )}
        >
          <Icon className="size-6" />
        </div>

        {/* Title */}
        <h3 className="mb-2 text-lg font-bold text-gray-900 dark:text-gray-100">
          {title}
        </h3>

        {/* Description */}
        <p className="text-sm leading-relaxed text-gray-600 dark:text-gray-400">
          {description}
        </p>
      </div>
    </div>
  );
}

