        >
          Paiement sécurisé par Stripe. Annulation facile, sans engagement.
        </motion.p>
      </div>
    </section>
  );
}

function PricingCard({
  plan,
  isYearly,
}: {
  plan: (typeof plans)[0];
  isYearly: boolean;
}) {
  const price = isYearly ? plan.price.yearly : plan.price.monthly;
  const Icon = plan.icon;

  return (
    <div
      className={cn(
        "glass-card relative flex h-full flex-col rounded-3xl p-8",
        plan.popular
          ? "ring-2 ring-primary shadow-lg"
          : "shadow-soft"
      )}
    >
      {/* Popular Badge */}
      {plan.popular && (
        <div className="absolute -top-4 left-1/2 -translate-x-1/2">
          <span className="rounded-full bg-primary px-4 py-1.5 text-sm font-bold text-white shadow-lg">
            Le plus populaire
          </span>
        </div>
      )}

      {/* Header */}
      <div className="mb-6">
        <div
          className={cn(
            "mb-4 inline-flex size-12 items-center justify-center rounded-2xl",
            plan.popular
              ? "bg-primary/10 text-primary"
              : "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400"
          )}
        >
          <Icon className="size-6" />
        </div>
        <h3 className="text-xl font-bold text-gray-900 dark:text-gray-100">
          {plan.name}
        </h3>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          {plan.description}
        </p>
      </div>

      {/* Price */}
      <div className="mb-6">
        <div className="flex items-baseline gap-1">
          <span className="text-4xl font-bold text-gray-900 dark:text-gray-100">
            {price === 0 ? "Gratuit" : `${price}€`}
          </span>
          {price > 0 && (
            <span className="text-sm text-gray-500">
              /{isYearly ? "an" : "mois"}
            </span>
          )}
        </div>
        {isYearly && price > 0 && (
          <p className="mt-1 text-xs text-sage">
            Soit {(price / 12).toFixed(2)}€/mois
          </p>
        )}
      </div>

      {/* Features */}
      <ul className="mb-8 flex-1 space-y-3">
        {plan.features.map((feature) => (
          <li key={feature} className="flex items-start gap-3">
            <Check
              className={cn(
                "mt-0.5 size-5 shrink-0",
                plan.popular ? "text-primary" : "text-sage"
              )}
            />
            <span className="text-sm text-gray-600 dark:text-gray-400">
              {feature}
            </span>
          </li>
        ))}
      </ul>

      {/* CTA */}
      <Link
        href={plan.ctaLink}
        className={cn(
          buttonVariants({ size: "lg" }),
          "w-full gap-2 rounded-2xl",
          plan.popular
            ? "bg-primary hover:bg-primary/90"
            : "bg-gray-900 hover:bg-gray-800 dark:bg-gray-100 dark:text-gray-900 dark:hover:bg-gray-200"
        )}
      >
        {plan.cta}
        <ArrowRight className="size-4" />
      </Link>
    </div>
  );
}

